package com.loja.checkout.dominio;

import java.math.BigDecimal;
import java.util.Optional;

/**
 * Região do cliente. A conta do seguro é a mesma em todas: só a alíquota muda,
 * então aqui basta guardar a alíquota.
 */
public enum Regiao {

    SUDESTE("0.01"),
    SUL("0.01"),
    CENTRO_OESTE("0.015"),
    NORTE("0.025"),
    NORDESTE("0.02");

    private final BigDecimal aliquotaSeguro;

    Regiao(String aliquotaSeguro) {
        this.aliquotaSeguro = new BigDecimal(aliquotaSeguro);
    }

    public BigDecimal seguro(BigDecimal subtotalProdutos) {
        return Dinheiro.percentual(subtotalProdutos, aliquotaSeguro);
    }

    public static Optional<Regiao> porCodigo(String codigo) {
        return Registro.busca(values(), Enum::name, codigo);
    }
}
EOF
cat > Registro.java <<'EOF'
package com.loja.checkout.dominio;

import java.util.Arrays;
import java.util.Collection;
import java.util.Optional;
import java.util.function.Function;

/** Resolve código -> caso, sem cadeia de condições. */
public final class Registro {

    private Registro() {
    }

    public static <T> Optional<T> busca(T[] casos, Function<T, String> codigo, String procurado) {
        return busca(Arrays.asList(casos), codigo, procurado);
    }

    public static <T> Optional<T> busca(Collection<T> casos, Function<T, String> codigo, String procurado) {
        if (procurado == null) {
            return Optional.empty();
        }
        return casos.stream()
                .filter(caso -> codigo.apply(caso).equals(procurado))
                .findFirst();
    }
}
EOF
