18	import org.springframework.stereotype.Service;
19	
20	import java.math.BigDecimal;
21	import java.util.List;
22	import java.util.Optional;
23	import java.util.function.Supplier;
24	
25	/** Monta o resumo da compra: valida na ordem definida e aplica as etapas do cálculo. */
26	@Service
27	public class ResumoService {
28	
29	    private static final int PARCELAS_PADRAO = 1;
30	
31	    public ResumoResponse calcular(ResumoRequest requisicao) {
32	        Pedido pedido = pedidoValido(requisicao.itens());
33	        NivelClube nivel = exigir(NiveisClube.porCodigo(requisicao.nivelClube()), CodigoErro.NIVEL_CLUBE_INVALIDO);
34	        Regiao regiao = exigir(Regiao.porCodigo(requisicao.regiao()), CodigoErro.REGIAO_INVALIDA);
35	        ModalidadeEntrega modalidade = exigir(
36	                ModalidadesEntrega.porCodigo(requisicao.modalidadeEntrega()), CodigoErro.MODALIDADE_INVALIDA);
37	        exigirQue(modalidade.atende(pedido), CodigoErro.MODALIDADE_INDISPONIVEL);
38	
39	        BigDecimal subtotal = pedido.subtotalProdutos();
40	        BigDecimal frete = nivel.isentaFrete() ? Dinheiro.ZERO : modalidade.frete(pedido);
41	        BigDecimal desconto = desconto(requisicao.cupom(), pedido, frete);
42	        BigDecimal seguro = regiao.seguro(subtotal);
43	        BigDecimal totalPedido = Dinheiro.centavos(subtotal.subtract(desconto).add(frete).add(seguro));
44	
45	        FormaPagamento forma = exigir(
46	                FormasPagamento.porCodigo(requisicao.formaPagamento()), CodigoErro.FORMA_PAGAMENTO_INVALIDA);
47	        int parcelas = requisicao.parcelas() == null ? PARCELAS_PADRAO : requisicao.parcelas();
48	        exigirQue(forma.aceitaParcelas(parcelas), CodigoErro.PARCELAMENTO_INVALIDO);
49	        exigirQue(forma.atende(totalPedido), CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
50	        Cobranca cobranca = forma.cobrar(totalPedido, parcelas);
51	
52	        return new ResumoResponse(
53	                subtotal,
54	                desconto,
55	                frete,
56	                modalidade.prazoDias(),
57	                seguro,
58	                Dinheiro.centavos(cobranca.totalFinal().subtract(totalPedido)),
59	                cobranca.totalFinal(),
60	                parcelas,
61	                cobranca.valorParcela(),
62	                nivel.credito(subtotal),
63	                nivel.brinde(subtotal));
64	    }
65	
66	    private BigDecimal desconto(String codigoCupom, Pedido pedido, BigDecimal frete) {
67	        if (codigoCupom == null || codigoCupom.isBlank()) {
68	            return Dinheiro.ZERO;
69	        }
70	        Cupom cupom = exigir(Cupons.porCodigo(codigoCupom), CodigoErro.CUPOM_INVALIDO);
71	        exigirQue(cupom.aplicavel(pedido), CodigoErro.CUPOM_NAO_APLICAVEL);
72	        return cupom.desconto(pedido, frete);
73	    }
74	
75	    private Pedido pedidoValido(List<ItemRequest> itens) {
76	        exigirQue(itens != null && !itens.isEmpty(), CodigoErro.PEDIDO_INVALIDO);
77	        return new Pedido(itens.stream().map(this::itemValido).toList());
78	    }
79	
80	    private ItemPedido itemValido(ItemRequest item) {
81	        exigirQue(item != null
82	                        && positivo(item.precoUnitario())
83	                        && item.quantidade() != null && item.quantidade() > 0
84	                        && positivo(item.pesoKg()),
85	                CodigoErro.PEDIDO_INVALIDO);
86	        return new ItemPedido(item.nome(), item.precoUnitario(), item.quantidade(), item.pesoKg());
87	    }
88	
89	    private boolean positivo(BigDecimal valor) {
90	        return valor != null && valor.compareTo(BigDecimal.ZERO) > 0;
91	    }
92	
93	    private <T> T exigir(Optional<T> caso, CodigoErro codigo) {
94	        return caso.orElseThrow(recusa(codigo));
95	    }
96	
97	    private void exigirQue(boolean condicao, CodigoErro codigo) {
98	        if (!condicao) {
99	            throw recusa(codigo).get();
100	        }
101	    }
102	
103	    private Supplier<PedidoRecusadoException> recusa(CodigoErro codigo) {
104	        return () -> new PedidoRecusadoException(codigo);
105	    }
106	}
