1	package com.loja.checkout.pagamento;
2	
3	import com.loja.checkout.dominio.Dinheiro;
4	
5	import java.math.BigDecimal;
6	import java.math.MathContext;
7	
8	/** Cartão de crédito: até 3x sem juros, de 4x a 12x com juros pela tabela Price. */
9	class Cartao implements FormaPagamento {
10	
11	    private static final int PARCELAS_MAXIMAS = 12;
12	    private static final int PARCELAS_SEM_JUROS = 3;
13	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
14	    private static final MathContext PRECISAO = MathContext.DECIMAL128;
15	
16	    @Override
17	    public String codigo() {
18	        return "CARTAO";
19	    }
20	
21	    @Override
22	    public boolean aceitaParcelas(int parcelas) {
23	        return parcelas >= 1 && parcelas <= PARCELAS_MAXIMAS;
24	    }
25	
26	    @Override
27	    public Cobranca cobrar(BigDecimal totalPedido, int parcelas) {
28	        if (parcelas <= PARCELAS_SEM_JUROS) {
29	            return new Cobranca(Dinheiro.centavos(totalPedido), divide(totalPedido, parcelas));
30	        }
31	        BigDecimal parcela = parcelaPrice(totalPedido, parcelas);
32	        return new Cobranca(Dinheiro.centavos(parcela.multiply(BigDecimal.valueOf(parcelas))), parcela);
33	    }
34	
35	    private BigDecimal divide(BigDecimal total, int parcelas) {
36	        return Dinheiro.centavos(total.divide(BigDecimal.valueOf(parcelas), PRECISAO));
37	    }
38	
39	    /** parcela = total x taxa / (1 - (1 + taxa)^-parcelas) */
40	    private BigDecimal parcelaPrice(BigDecimal total, int parcelas) {
41	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, PRECISAO);
42	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, PRECISAO));
43	        return Dinheiro.centavos(total.multiply(TAXA_MENSAL).divide(divisor, PRECISAO));
44	    }
45	}
