3	import java.math.BigDecimal;
4	
5	/** Forma sempre à vista: uma parcela só, igual ao valor final. */
6	abstract class AVista implements FormaPagamento {
7	
8	    @Override
9	    public boolean aceitaParcelas(int parcelas) {
10	        return parcelas == 1;
11	    }
12	
13	    @Override
14	    public Cobranca cobrar(BigDecimal totalPedido, int parcelas) {
15	        BigDecimal totalFinal = totalFinalAVista(totalPedido);
16	        return new Cobranca(totalFinal, totalFinal);
17	    }
18	
19	    protected abstract BigDecimal totalFinalAVista(BigDecimal totalPedido);
20	}
